import{_ as a,o as s,c as t,a3 as n}from"./chunks/framework.BJY4yM9V.js";const u=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/architecture.md","filePath":"explanation/architecture.md"}'),o={name:"explanation/architecture.md"};function r(i,e,p,c,d,h){return s(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>Hypha is the <em>substrate</em> layer: distributed primitives over generic entities. It owns who may act on an entity, when, and on which machine — plus the transport that gets ops and snapshots there.</p><h2 id="where-it-sits" tabindex="-1">Where it sits <a class="header-anchor" href="#where-it-sits" aria-label="Permalink to &quot;Where it sits&quot;">​</a></h2><p>The org stack is <strong>delivery → memory → process → interface</strong>. Hypha is the <strong>distributed substrate</strong> — the connective layer between nodes and workloads, at the base of the delivery layer: the substrate that syncs entities across nodes. Integrations (sepia&#39;s session plane, peregrin&#39;s campaigns, future kinds) register their entity planes <em>on</em> hypha; the process layer (<code>peregrin</code>) orchestrates campaigns on this substrate and never the reverse; readers (<code>pavo</code>, the <code>hypha</code> CLI) read the merged index and submit ops through the hub.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                 ┌─────────────── hypha-hub ───────────────┐</span></span>
<span class="line"><span>                 │  merged index · op routing · push · SSE  │</span></span>
<span class="line"><span>                 └──────────────┬───────────────┬──────────┘</span></span>
<span class="line"><span>                        HTTP+SSE │               │ HTTP+SSE</span></span>
<span class="line"><span>                  ┌──────────────▼──┐    ┌───────▼──────────┐</span></span>
<span class="line"><span>                  │ hypha node A    │    │ hypha node B     │</span></span>
<span class="line"><span>                  │ /api/entities*  │    │ /api/entities*   │</span></span>
<span class="line"><span>                  │ KindRegistry    │    │ KindRegistry     │</span></span>
<span class="line"><span>                  └───────┬─────────┘    └────────┬─────────┘</span></span>
<span class="line"><span>                          │  integrations register entity planes:</span></span>
<span class="line"><span>              ┌───────────┼───────────────────────┼───────────┐</span></span>
<span class="line"><span>              ▼           ▼                       ▼           ▼</span></span>
<span class="line"><span>        sepia-session  campaign-run          &lt;kind-N&gt;     entity.*</span></span>
<span class="line"><span>        (sepia repo)   (peregrin repo)       (any repo)   (substrate)</span></span></code></pre></div><h2 id="planes" tabindex="-1">Planes <a class="header-anchor" href="#planes" aria-label="Permalink to &quot;Planes&quot;">​</a></h2><ul><li><strong>Entity plane</strong> — this repo: <code>EntityApi</code> contract (<code>hypha-node-api</code>), node host (<code>hypha serve</code>, <code>hypha-node</code> + <code>hypha-http</code>), hub gateway (<code>hypha-hub</code>), projection (<code>hypha-sync</code>), outbox (<code>hypha-outbox</code>), arbitration (<code>hypha-control</code>), push.</li><li><strong>Integration planes</strong> — one per workload kind, living in the workload&#39;s own repo: <code>sepia-peregrin</code> (sepia repo) registers <code>kind=&quot;sepia-session&quot;</code>; peregrin registers <code>kind=&quot;campaign&quot;</code>. An integration translates entity ops ↔ its verbs and implements snapshot as its own serialize/resume.</li><li><strong>Orchestration plane</strong> — campaigns, drivers, loaders. Stays in peregrin; becomes a <em>workload on</em> hypha rather than a peer of it.</li></ul><h2 id="ports-and-adapters" tabindex="-1">Ports and adapters <a class="header-anchor" href="#ports-and-adapters" aria-label="Permalink to &quot;Ports and adapters&quot;">​</a></h2><p>The substrate&#39;s own I/O seam is <code>hypha-kv</code> (node-local KV, <code>-file</code> impl); hub node credentials go through the <code>keyring</code> crate with a file fallback. The generic half of ports-and-adapters lives in sibling repos now — secrets resolve through cuora&#39;s <code>cuora-secret*</code> family and service lifecycle through tamias&#39;s <code>tamias-deploy-*</code> where a consumer needs them, and telemetry is <code>lampy-telemetry(-otel)</code> — so no <code>hypha-secret</code>/<code>hypha-service</code>/ <code>hypha-telemetry</code> crates remain. The substrate contracts are pure — <code>hypha-control</code> has no I/O at all.</p><h2 id="dataflow" tabindex="-1">Dataflow <a class="header-anchor" href="#dataflow" aria-label="Permalink to &quot;Dataflow&quot;">​</a></h2><p>Client → hub <code>POST /api/entities/{id}/ops</code> → lock gate (<code>hypha-control</code>) → owner node <code>POST /api/entities/{id}/ops</code> → the kind&#39;s <code>EntityPlane::op</code>. Node down? <code>hypha-outbox</code> FIFO per entity, replayed oldest-first on reconnect. Reads merge through <code>hypha-sync</code>&#39;s SQLite projection + SSE diff tail.</p>`,11)])])}const y=a(o,[["render",r]]);export{u as __pageData,y as default};
